SourceCode.Declaration:
/// <summary>
/// Stamps the label-preview default values onto the WHSParameters record when the parameters form
/// opens, so they are visible on the form even for records created before these fields existed
/// (the table's initValue covers only newly created records). One-time and idempotent: it writes
/// only when a field is unset and the user has Edit access.
/// </summary>
[ExtensionOf(formStr(WHSParameters))]
final class WHSParametersForm_AAXWarehouseTools_Extension
{
}

Method.Source:
public void init()
{
    WHSParameters parameters;

    next init();

    // Runs before the form data source executes its query, so the stamped values are the ones
    // displayed. Skip silently without Edit access (read-only users still get the runtime
    // defaults via the accessors).
    if (!hasTableAccess(tableNum(WHSParameters), AccessType::Edit))
    {
        return;
    }

    ttsbegin;
    select forupdate firstonly parameters;

    if (parameters
        && (!parameters.AAXPreviewAutoOffDays
         || !parameters.AAXPreviewRetentionDays
         || !parameters.AAXPreviewDefaultDpi
         || !parameters.AAXPreviewDefaultWidthIn
         || !parameters.AAXPreviewDefaultHeightIn))
    {
        parameters.aaxApplyPreviewDefaultsIfUnset();
        parameters.update();
    }
    ttscommit;
}
